"""Roman numeral conversion for 1..3999."""

_TABLE = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
          (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]


def to_roman(n):
    if isinstance(n, bool) or not isinstance(n, int) or not 1 <= n <= 3999:
        raise ValueError(f"out of range (1-3999): {n!r}")
    out = []
    for v, s in _TABLE:
        while n >= v:
            out.append(s)
            n -= v
    return "".join(out)


def from_roman(s):
    if not isinstance(s, str) or not s:
        raise ValueError(f"invalid roman numeral: {s!r}")
    n, i = 0, 0
    for v, sym in _TABLE:
        while s.startswith(sym, i):
            n += v
            i += len(sym)
    if i != len(s) or n > 3999 or to_roman(n) != s:
        raise ValueError(f"invalid roman numeral: {s!r}")
    return n
